import json, pathlib, hashlib, subprocess
root=pathlib.Path('/home/akisarou/.cache/nts-scratch/760')
tree=pathlib.Path('/home/akisarou/.cache/nts-pool/5')
def read(name): return json.loads((root/name).read_text())
def sha(path): return hashlib.sha256(path.read_bytes()).hexdigest()
cohorts={}
for name in ['real-overhead-v3','real-overhead-v4','real-cpu-v3','real-cpu-v4','real-cpu-v5','real-overhead-v6','real-cpu-v6','real-overhead-v7']:
    path=root/name/'provenance.json'
    if not path.exists():
        path=root/name/'provenance.partial.json'
    if not path.exists(): continue
    raw=json.loads(path.read_text()); rows=raw['rows']; summary={}
    for backend in ['c','llvm','jvm']:
        arms=[row for row in rows if row['name'].startswith(backend+'-')]
        off=[row for row in arms if not row['enabled']]; on=[row for row in arms if row['enabled']]
        if not off or not on: continue
        summary[backend]={
          'ordinary_or_perf_cpu_ratio':sum(row['cpu_s']+row['collection_cpu_s'] for row in on)/sum(row['cpu_s'] for row in off),
          'user_instructions_ratio':sum(row['instructions'] for row in on)/sum(row['instructions'] for row in off) if all(row['instructions'] for row in arms) else None,
          'off_cpu_s':[row['cpu_s'] for row in off], 'on_cpu_s':[row['cpu_s'] for row in on],
          'on_collection_cpu_s':[row['collection_cpu_s'] for row in on]}
    cohorts[name]={'raw':str(path),'sha256':sha(path),'observer':rows[0].get('observer','perf-inherited' if 'overhead' in name else 'none'), 'provenance':raw,'summary':summary}
identity=read('recheck-v2/identity-summary.json')
wiring=read('wiring-v5/summary.json')
result={'version':1,'issue':760,'source':subprocess.check_output(['git','--no-optional-locks','rev-parse','HEAD'],cwd=tree,text=True).strip(),
  'writer':str(pathlib.Path(__file__)),'writer_source':pathlib.Path(__file__).read_text(),'writer_sha256':sha(pathlib.Path(__file__)),
  'recovery_check':{'source':(root/'recover-cpu-manifest.py').read_text(),'sha256':sha(root/'recover-cpu-manifest.py')},
  'executed_ordinary_script':{'source':(root/'real-cpu-v6.ts').read_text(),'sha256':sha(root/'real-cpu-v6.ts')},
  'identity':{key:value for key,value in identity.items() if key!='raw_byte_classification'},
  'identity_raw':{'path':str(root/'recheck-v2/identity-summary.json'),'sha256':sha(root/'recheck-v2/identity-summary.json')},
  'wiring':{key:{'scope':next(row for row in wiring['rows'] if row['name']==key),'phases':value['census_phases']} for key,value in wiring['case_costs']['steps'].items() if 'census_phases' in value},
  'cohorts':cohorts,
  'component_profiles':{name:read(name+'/provenance.json') for name in ['profile-components','profile-components-v2','profile-components-perf']},
  'measurement_source':'96efb519b77454da298716e54b0acb24d9094632',
  'production_configuration':{'step_wrapper':'tooling/gate/run.mjs wraps with /usr/bin/time, never perf; the eight all.sh routes call the census directly','step_cpu_measure':'cgroup-v2-scope-v1','collection_cpu_measure':'getrusage-self-v1, synchronous collector with no children','acceptance':'ordinary step cgroup CPU plus separately charged ON collection CPU; counted instructions shown alongside, never mixed with ordinary CPU'},
  'canonical':read('canonical-result.json'),
  'measurement_notes':['CPU ratios include separately observed collection CPU.', 'Perf inherited-event runs include fork/PMU observer cost and are separate from ordinary execution.', 'Earlier short/cohort, cold, stopped and unmeasured attempts remain under the protected scratch root; their status is recorded in the notebook.']}
output=tree/'results/gate/census-phases-760.json';output.parent.mkdir(parents=True,exist_ok=True);output.write_text(json.dumps(result,indent=2)+'\n')
print(output, output.stat().st_size)
for name,value in cohorts.items(): print(name,{backend:round(data['ordinary_or_perf_cpu_ratio'],6) for backend,data in value['summary'].items()})

