import {spawn} from 'node:child_process';
import {mkdirSync,readFileSync,writeFileSync} from 'node:fs';
import {join} from 'node:path';
import {pathToFileURL} from 'node:url';
import {createHash} from 'node:crypto';
const tree='/home/akisarou/.cache/nts-pool/5',base='/home/akisarou/.cache/nts-scratch/760/real-cpu-v6';
const USE_PERF=false;
const load=(file:string)=>import(pathToFileURL(join(tree,file)).href);
async function main(){
  mkdirSync(base,{recursive:true});
  const {gateEnvironment,sealOracleRun}=await load('tooling/gate/canonical-environment.ts');
  const {MemoryRun}=await load('tooling/census/worker-memory.ts');
  const {hostObservations}=await load('tooling/gate/host-observations.ts');
  const {prepareChildObserver}=await load('tooling/gate/child-rusage.ts');
  const {PERF_ARGS,parseMeasurement,counterProblem}=await load('tooling/gate/cputime.mjs');
  const {typeScriptOracleDirectory}=await load('tooling/census/typescript-oracle-capture.ts');
  const {typeScriptOracleHandoff}=await load('tooling/census/typescript-oracle-results.ts');
  const {summarizeCosts}=await load('tooling/gate/case-costs.ts');
  const bin=join(tree,'target/release/nts');
  const env=(await sealOracleRun(gateEnvironment(process.env,{run:join(base,'context'),oracleRoot:tree,owned:{NTS_BIN:bin,NTS_CHECKERS:'1',NTS_MEMORY_RESERVATION:process.env.NTS_MEMORY_RESERVATION,NTS_JVM_CDS_DIR:join(base,'cds')}}))).env;
  const memory=new MemoryRun({id:'real-phase-overhead',budgetBytes:6_144_000_000}),rows:any[]=[];let index=0;
  const run=async(name:string,args:string[],enabled:boolean,counted:boolean)=>{
    const costs=join(base,name+'-costs');mkdirSync(costs,{recursive:true});
    if(enabled){const prepared=prepareChildObserver(costs,env);if(prepared.error)throw Error(prepared.error);}
    const worker=memory.worker(index++,6_144_000_000),counter=join(base,name+'.perf');
    const supplied={...env,NTS_GATE_STEP:name==='oracles'?'typescript-oracles':'typescript-'+args[args.indexOf('--backend')+1]};
    if(name!=='oracles')supplied.NTS_TYPESCRIPT_ORACLE=JSON.stringify(typeScriptOracleHandoff(join(typeScriptOracleDirectory(env),'results')));
    if(enabled)supplied.NTS_GATE_CASE_COSTS_DIR=costs;else delete supplied.NTS_GATE_CASE_COSTS_DIR;
    const target=counted&&USE_PERF?['-c','4','perf',...PERF_ARGS,'-o',counter,'--',process.execPath,...args]:['-c','4',process.execPath,...args];
    const scope=worker.scope('taskset',target,supplied),host=hostObservations(env),meter=host.scopeMemoryPeak(worker.group),before=host.load(),start=host.now();
    const child=spawn('systemd-run',scope.argv,{env:scope.env,cwd:tree,stdio:['ignore','pipe','pipe']});
    let stdout='',stderr='';child.stdout.on('data',part=>{stdout+=part;});child.stderr.on('data',part=>{stderr+=part;});
    try{
      const status=await new Promise<number|null>((resolve,reject)=>{child.on('error',reject);child.on('close',resolve);});
      writeFileSync(join(base,name+'.stdout'),stdout);writeFileSync(join(base,name+'.stderr'),stderr);
      if(status!==0)throw Error(name+' failed: '+status+'\n'+stderr);
      if(counted){
        const waited=USE_PERF?parseMeasurement(readFileSync(counter,'utf8')):null,problem=waited?counterProblem(waited):null;if(problem)throw Error(name+': '+problem);
        const cpu=host.cgroupCpu(worker.group),wall_s=(host.now()-start)/1000,peak_bytes=meter.read(),after=host.load();
        const phaseStart=host.ownCpu();
        const phases=enabled?summarizeCosts(costs,[],[{name:supplied.NTS_GATE_STEP,cpu:cpu.usageUsec/1e6,cpu_measure:'cgroup-v2-scope-v1'}]):null;
        const phaseEnd=host.ownCpu();
        const row={name,enabled,instructions:waited?.instructions??null,waited,observer:USE_PERF?'perf-inherited':'none',cpu_s:cpu.usageUsec/1e6,cpu_measure:'cgroup-v2-scope-v1',wall_s,peak_bytes,load_before:before,load_after:after,
          collection_cpu_s:((phaseEnd.userUsec-phaseStart.userUsec)+(phaseEnd.systemUsec-phaseStart.systemUsec))/1e6};
        rows.push(row);writeFileSync(join(base,name+'-phases.json'),JSON.stringify(phases,null,2)+'\n');
        writeFileSync(join(base,'rows.json'),JSON.stringify(rows,null,2)+'\n');process.stdout.write(JSON.stringify(row)+'\n');
      }
    }finally{meter.close();worker.close();await worker.closed;}
  };
  try{
    await run('oracles',[join(tree,'tooling/census/typescript-oracles.ts'),'--sample','500','--jobs','1'],false,false);
    for(const backend of ['c','llvm','jvm']){
      const command=(name:string)=>[join(tree,'tooling/census/conformance262.ts'),'--suite','typescript','--backend',backend,'--under','tests/typescript','--recorded',join(tree,'results/typescript',backend,'cases.tsv'),'--sample','500','--jobs','1','--json',join(base,name+'-result.json')];
      await run(backend+'-prime',command(backend+'-prime'),false,false);
      await run(backend+'-prime2',command(backend+'-prime2'),true,false);
      for(const [arm,enabled] of [['a',false],['b',true],['c',true],['d',false],['e',true],['f',false],['g',false],['h',true]] as const){
        const name=backend+'-'+arm;await run(name,command(name),enabled,true);
      }
      const products=['a','b','c','d','e','f','g','h'].map(arm=>{const result=JSON.parse(readFileSync(join(base,backend+'-'+arm+'-result.json'),'utf8'));return JSON.stringify({selected:result.selected,population:result.population,attempted:result.attempted,tally:result.tally,outcomes:result.outcomes});});
      if(new Set(products).size!==1)throw Error(backend+' performed different work between arms');
    }
    writeFileSync(join(base,'provenance.json'),JSON.stringify({source:spawnSync('git',['--no-optional-locks','rev-parse','HEAD'],{cwd:tree,encoding:'utf8'}).stdout.trim(),binary:bin,binarySha256:createHash('sha256').update(readFileSync(bin)).digest('hex'),sample:500,source:'production conformance262 TypeScript selector',rows},null,2)+'\n');
  }finally{memory.close();await memory.closed;}
}
main().catch(error=>{console.error(error);process.exitCode=1;});
